#!/bin/sh
# Regenerates src/bindings.rs from bugsplat-native's C header. Needs bindgen-cli and libclang
# (cargo install bindgen-cli). The output is checked in so users never need libclang.
set -eu
cd "$(dirname "$0")/.."
bindgen bugsplat-native/include/bugsplat/bugsplat.h \
  --allowlist-function 'bugsplat_.*' \
  --allowlist-type 'bugsplat_.*' \
  --allowlist-var 'BUGSPLAT_.*' \
  --newtype-enum 'bugsplat_.*' \
  --no-layout-tests \
  --use-core \
  --merge-extern-blocks \
  --raw-line '// Generated by scripts/generate-bindings.sh from bugsplat-native/include/bugsplat/bugsplat.h. Do not edit.' \
  -o src/bindings.rs \
  -- -DBUGSPLAT_STATIC -Ibugsplat-native/include
